
.meter {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.meter-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.meter-label {
  flex: none;
  width: 40px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.06em;
}

/* 细长条：4px 高，不带圆角，像账本上划的一道 */
.meter-track {
  position: relative;
  flex: 1 1 auto;
  height: 4px;
  background: var(--c-border);
}

.meter-fill {
  position: absolute;
  inset: 0 auto 0 0;
  transition: width var(--t-hard);
}

.meter-value {
  flex: none;
  min-width: 26px;
  font-size: 11px;
  font-style: normal;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.meter-hint {
  margin: 0;
  padding-left: 47px;
  color: var(--c-text-muted);
  font-size: 10px;
  line-height: 1.45;
}
