
.block {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 9px 10px;
  background: var(--c-surface-raised);
  border-left: 2px solid var(--c-border);
  /* 明线：梦没发生时不打扰你 */
  transition:
    border-color var(--t-dream),
    background var(--t-dream);
}

/* 暗线接管：共梦发生的那一天，整块渗出来 */
.dream.lit {
  border-left-color: var(--c-dream);
  background: color-mix(in srgb, var(--c-dream) 8%, var(--c-surface-raised));
}

.dream.nightmare {
  border-left-color: var(--c-hate);
  background: color-mix(in srgb, var(--c-hate) 10%, var(--c-surface-raised));
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;

  i {
    transition: color var(--t-dream);
  }
}

.dream.lit .block-head i {
  color: var(--c-dream-text);
}

.dream.nightmare .block-head i {
  color: var(--c-hate-text);
}

.tone {
  margin-left: auto;
  padding: 1px 6px;
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.08em;
  border: 1px solid var(--c-border);
  transition:
    color var(--t-dream),
    border-color var(--t-dream);
}

.tone-sink {
  color: var(--c-dream-text);
  border-color: var(--c-dream-text);
}

.tone-lost {
  color: var(--c-hate-text);
  border-color: var(--c-hate-text);
}

.tone-none {
  color: var(--c-text-muted);
}

.facts {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;

  > div {
    display: flex;
    flex-direction: column;
    gap: 1px;
  }

  dt {
    color: var(--c-text-muted);
    font-size: 9px;
    letter-spacing: 0.06em;
  }

  dd {
    margin: 0;
    font-size: 11px;
    line-height: 1.5;
  }
}

.quiet {
  margin: 0;
  color: var(--c-text-muted);
  font-size: 10px;
  line-height: 1.5;
}

/* ── 物证清单 ───────────────────────────────────────────────── */
.evidence {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 9px;
  background: rgb(0 0 0 / 22%);
  border-top: 1px solid var(--c-border);
}

.evidence-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-dream-text);
  font-size: 10px;
  letter-spacing: 0.1em;

  em {
    margin-left: auto;
    color: var(--c-text-muted);
    font-size: 9px;
    font-style: normal;
  }
}

.dream.nightmare .evidence-head {
  color: var(--c-hate-text);
}

.evidence-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: flex;
    align-items: baseline;
    gap: 7px;
  }
}

.no {
  flex: none;
  color: var(--c-text-muted);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

/* 完整展示，不截断 */
.text {
  font-size: 11px;
  line-height: 1.55;
}

.witness {
  margin: 0;
  color: var(--c-text-muted);
  font-size: 9px;
  line-height: 1.5;
  font-style: italic;
}

/* 失控度高位：留痕开始「不安分」——她已经不打算醒过来了 */
.dream.nightmare .evidence-list {
  animation: unsettle 3.4s ease-in-out infinite;
}

@keyframes unsettle {
  0%,
  100% {
    transform: translateX(0);
  }
  46% {
    transform: translateX(0);
  }
  48% {
    transform: translateX(-0.6px);
  }
  50% {
    transform: translateX(0.6px);
  }
  52% {
    transform: translateX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dream.nightmare .evidence-list {
    animation: none;
  }
}
