
.block {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;

  .hint {
    margin-left: auto;
    font-size: 9px;
    font-style: normal;
    letter-spacing: 0.02em;
    opacity: 0.7;
  }
}

.ladder {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rung {
  display: flex;
  gap: 8px;
  padding: 4px 0 4px 2px;
  /* 未抵达的阶段压暗：她还没走到那一步（0.4 会掉到读不清，取 0.5） */
  opacity: 0.5;
  transition: opacity var(--t-hard);

  &.reached {
    opacity: 1;
  }

  &.current {
    background: rgb(213 209 200 / 5%);
  }
}

.pip {
  flex: none;
  width: 6px;
  height: 6px;
  margin-top: 6px;
  background: var(--c-border);
  transition: background var(--t-dream);
}

.rung-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.rung-top {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.rung-name {
  font-family: var(--font-serif);
  font-size: 12px;
  letter-spacing: 0.04em;
}

.rung-index {
  color: var(--c-text-muted);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.rung-gate {
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.02em;
}

.note {
  margin: 0;
  color: var(--c-primary);
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.85;
}
