
.block {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;

  .hint {
    margin-left: auto;
    font-size: 9px;
    font-style: normal;
    letter-spacing: 0.02em;
    opacity: 0.7;
  }
}

.label {
  display: flex;
  align-items: baseline;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.count {
  margin-left: auto;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

/* 筹码：金色 —— 这是你手里唯一能上桌的东西 */
.assets {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.assets-text {
  margin: 0;
  padding-left: 7px;
  border-left: 2px solid var(--c-gold);
  color: var(--c-primary);
  font-size: 11px;
  line-height: 1.55;
}

.intel {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 5px;
  border-top: 1px solid var(--c-border);
}

.intel-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: flex;
    align-items: baseline;
    gap: 6px;
    font-size: 11px;
    line-height: 1.5;
  }

  i {
    flex: none;
    color: var(--c-gold);
    font-size: 9px;
  }
}

.intel-empty {
  margin: 0;
  color: var(--c-text-muted);
  font-size: 10px;
  line-height: 1.5;
}
