
.block {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;

  .hint {
    margin-left: auto;
    font-size: 9px;
    font-style: normal;
    letter-spacing: 0.02em;
    opacity: 0.7;
  }
}

.axis {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.track-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.tag {
  flex: none;
  width: 15px;
  font-family: var(--font-serif);
  font-size: 12px;
  line-height: 1;
  text-align: center;
}

.tag-hate {
  color: var(--c-hate-text);
}

.tag-desire {
  color: var(--c-desire-text);
}

.track {
  position: relative;
  flex: 1 1 auto;
  height: 5px;
  background: var(--c-border);
}

/* 共享中轴：两根条朝这里推进 */
.track::after {
  content: '';
  position: absolute;
  top: -3px;
  bottom: -3px;
  left: 50%;
  width: 1px;
  background: var(--c-text-muted);
  opacity: 0.55;
}

.fill {
  position: absolute;
  top: 0;
  bottom: 0;
  transition: width var(--t-dream);
}

/* 恨：锚在右端，向左推 */
.fill-hate {
  right: 0;
  background: var(--c-hate);
}

/* 欲：锚在左端，向右推 */
.fill-desire {
  left: 0;
  background: var(--c-desire);
}

.num {
  flex: none;
  min-width: 26px;
  font-size: 12px;
  font-style: normal;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.num-hate {
  color: var(--c-hate-text);
}

.num-desire {
  color: var(--c-desire-text);
}

.read {
  margin: 0;
  color: var(--c-primary);
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.85;
}

.ranges {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding-top: 4px;
  border-top: 1px solid var(--c-border);
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.04em;
}
