
.block {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;

  .hint {
    margin-left: auto;
    font-size: 9px;
    font-style: normal;
    letter-spacing: 0.02em;
    opacity: 0.7;
  }
}

.facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 5px 10px;
  margin: 0;

  > div {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .wide {
    grid-column: 1 / -1;
  }

  dt {
    color: var(--c-text-muted);
    font-size: 9px;
    letter-spacing: 0.06em;
  }

  dd {
    margin: 0;
    font-size: 11px;
    line-height: 1.5;
  }
}

.mono {
  font-variant-numeric: tabular-nums;
}

.time {
  margin-left: 5px;
  color: var(--c-gold);
}

.bid {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 5px;
  border-top: 1px solid var(--c-border);
}

.bid-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.bid-label {
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.bid-days {
  margin-left: auto;
  color: var(--c-text-muted);
  font-size: 10px;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.bid.near .bid-days {
  color: var(--c-gold);
}

/* 90 天刻度尺：一条静态的尺，不是进度条 */
.ruler {
  position: relative;
  display: block;
  height: 3px;
  background: var(--c-border);
}

.ruler-mark {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  margin-left: -1px;
  background: var(--c-text-muted);
  transition: left var(--t-dream);
}

.bid.near .ruler-mark {
  background: var(--c-gold);
}

.bid-note {
  margin: 0;
  color: var(--c-text-muted);
  font-size: 9px;
  line-height: 1.5;
}
