
.badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex: none;
}

/* 篆印式方章：两字竖排，边框取阶段色阶 */
.seal {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  padding: 2px 4px;
  font-family: var(--font-serif);
  font-size: 11px;
  line-height: 1.05;
  letter-spacing: 0;
  color: var(--stage-ink);
  border: 1px solid var(--stage-ink);
  /* 支持 color-mix 时渗出一点阶段色，不支持则退回木饰面底色 */
  background: var(--c-surface-raised);
  background: color-mix(in srgb, var(--stage) 18%, var(--c-surface));
  transition:
    color var(--t-dream),
    border-color var(--t-dream);
}

.seal em {
  font-style: normal;
}

.doom {
  font-size: 10px;
  line-height: 1;
  color: var(--c-hate-text);
}
