
.ledger {
  position: relative;
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  overflow: hidden;
  transition: border-color var(--t-dream);
}

.is-nightmare {
  border-color: color-mix(in srgb, var(--c-hate) 55%, var(--c-border));
}

/* 暗线接管：共梦发生的那一天，整张卡渗出水汽；噩梦那一夜换成血色的 */
.ledger::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--t-dream);
  background:
    radial-gradient(120% 80% at 12% 0%, rgb(107 116 168 / 12%), transparent 60%),
    radial-gradient(100% 90% at 92% 100%, rgb(107 116 168 / 9%), transparent 62%);
}

.is-dreaming::after {
  opacity: 1;
}

.is-nightmare::after {
  background:
    radial-gradient(120% 80% at 12% 0%, rgb(142 43 48 / 17%), transparent 60%),
    radial-gradient(100% 90% at 92% 100%, rgb(142 43 48 / 12%), transparent 62%);
}

/* ── 标题栏 ─────────────────────────────────────────────────── */
.rail {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 12px 8px;
  background: transparent;
  border: 0;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.rail:hover {
  background: rgb(213 209 200 / 3%);
}

.ident {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
}

/* 衬线体标题：老钱、碑铭那种字体 */
.ident-name {
  font-family: var(--font-serif);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: 0.16em;
  color: var(--c-gold);
}

.ident-where {
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.04em;
}

.dream-flag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.06em;
  transition: color var(--t-dream);
}

.dream-flag i {
  font-size: 10px;
}

.dream-flag em {
  font-style: normal;
}

.dream-flag.lit {
  color: var(--c-dream-text);
}

.is-nightmare .dream-flag.lit {
  color: var(--c-hate-text);
}

.gauge {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 0 6px;
  flex: none;
}

.gauge-label {
  color: var(--c-text-muted);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.08em;
}

.gauge-value {
  color: var(--c-reckless-text);
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.gauge-track {
  grid-column: 1 / -1;
  position: relative;
  display: block;
  width: 74px;
  height: 3px;
  background: var(--c-border);
}

.gauge-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--c-reckless);
  transition: width var(--t-dream);
}

.is-doomed .gauge-value {
  color: var(--c-hate-text);
}

.is-doomed .gauge-fill {
  background: var(--c-hate);
}

.stamp {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex: none;
  font-variant-numeric: tabular-nums;
}

.stamp-date {
  color: var(--c-primary);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.02em;
}

.stamp-time {
  color: var(--c-gold);
  font-size: 12px;
  letter-spacing: 0.04em;
}

.caret {
  flex: none;
  color: var(--c-text-muted);
  font-size: 11px;
  transition: transform var(--t-hard);
}

.caret.up {
  transform: rotate(180deg);
}

/* ── 情境条带 ───────────────────────────────────────────────── */
.band {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 5px 12px;
  font-size: 11px;
  line-height: 1.5;
  border-top: 1px solid var(--c-border);
}

.band i {
  flex: none;
  margin-top: 2px;
  font-size: 10px;
}

.band-nightmare {
  background: rgb(142 43 48 / 15%);
  border-top-color: rgb(142 43 48 / 42%);
  color: var(--c-hate-text);
}

.band-ntr {
  background: rgb(180 98 42 / 12%);
  border-top-color: rgb(180 98 42 / 38%);
  color: var(--c-reckless-text);
}

.band-doomed {
  background: rgb(142 43 48 / 9%);
  border-top-color: rgb(142 43 48 / 30%);
  color: var(--c-hate-text);
}

.band-doomed i {
  animation: fade-ghost 2.6s ease-in-out infinite;
}

@keyframes fade-ghost {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .band-doomed i {
    animation: none;
  }
}

/* ── 展开区 ─────────────────────────────────────────────────── */
.body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 12px 13px;
  border-top: 1px solid var(--c-border);
}

.meters {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 10px;
  background: var(--c-surface-raised);
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 12px;
}

/* 交互人格：明线硬切（她不会给你过渡），暗线延迟渐显（梦的滞后） */
.panel-enter-active,
.panel-leave-active {
  transition: opacity var(--t-hard);
}

.is-dreaming .panel-enter-active,
.is-dreaming .panel-leave-active {
  transition: opacity var(--t-dream);
}

.panel-enter-from,
.panel-leave-to {
  opacity: 0;
}
